int compare_ints(const void *a, const void *b) {
    int arg1 = *(const int *)a;
    int arg2 = *(const int *)b;
    return (arg1 > arg2) - (arg1 < arg2);
}
void sort_sequence(int n, int arr[]) {
    qsort(arr, n, sizeof(int), compare_ints);
}

int find_minimum_range(int n, int k, int arr[]) {
    int keep = n - k;
    int result = arr[keep - 1] - arr[0];
    for (int start = 1; start + keep <= n; start++) {
        int diff = arr[start + keep - 1] - arr[start];
        if (diff < result) result = diff;
    }
    return result;
}

